from pathlib import Path
from html import escape
import re, json

ROOT=Path(__file__).resolve().parent
DIST=ROOT/'dist'
ORIGINAL='https://www.compassmitte.net/'
NAV=[('Startseite','index.html'),('Die Idee & Urtext','die-idee/index.html'),('Newsroom','blog/index.html'),('Beiträge','beitraege/index.html'),('Jetzt unterzeichnen','jetzt-unterzeichnen/index.html'),('Unterzeichnerinnen & Unterzeichner','die-unterstuetzer/index.html'),('Kontakt','kontakt-2/index.html'),('Impressum','52-2/index.html')]
def link(base,route):return base+route
def shell(title,route,base,main):
 nav=''.join(f'<a href="{base}{p}"'+(' aria-current="page"' if p==route or (route.startswith('beitraege/') and p=='beitraege/index.html') else '')+f'>{label}</a>' for label,p in NAV)
 footer=''.join(f'<a href="{base}{p}">{label}</a>'for label,p in NAV)
 return f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="description" content="Gestaltungsvorschau von CompassMitte: {escape(title)}"><meta name="theme-color" content="#173b3d"><link rel="icon" type="image/png" href="{base}assets/compass-mitte-logo-original.png"><title>{escape(title)} | CompassMitte · Vorschau</title><link rel="stylesheet" href="{base}assets/style.css"><link rel="stylesheet" href="{base}assets/vorschau.css?v=urtext1"><script src="{base}assets/vorschau.js" defer></script></head><body><a class="skip" href="#inhalt">Zum Inhalt springen</a><div class="preview-bar"><div class="wrap"><span>GESTALTUNGSVORSCHAU · Entwurf zur Abstimmung</span><span class="preview-date">Stand 19. Oktober 2026</span></div></div><div class="wrap"><header class="header v2header"><div class="header-main"><a class="brand" href="{base}index.html" aria-label="CompassMitte, Startseite"><img class="original-logo" src="{base}assets/compass-mitte-logo-original.png" width="1231" height="768" alt="CompassMitte"></a><span class="brand-line">Auf das C kommt es an.</span><button class="menu-toggle" aria-controls="site-nav" aria-expanded="false">Menü</button></div><nav class="nav" id="site-nav" aria-label="Hauptnavigation">{nav}</nav></header></div>{main}<div class="wrap"><footer><div class="footer-top"><a class="brand footer-brand" href="{base}index.html"><img class="original-logo" src="{base}assets/compass-mitte-logo-original.png" width="1231" height="768" alt="CompassMitte"></a><span class="fine">Christlich-sozial. Liberal. Konservativ.</span></div><nav class="footer-links" aria-label="Fußnavigation">{footer}</nav><p class="footer-note">Gestaltungsvorschau des neuen Auftritts. Formulare dienen nur zur Ansicht und übertragen keine Angaben. Die bestehende Website unter compassmitte.net bleibt unverändert. <a href="{base}52-2/index.html#vorschau">Hinweise zur Vorschau</a></p></footer></div></body></html>'''
def heading(title,kicker,lead,base='../'):
 return f'<nav class="breadcrumb" aria-label="Brotkrümelnavigation"><a href="{base}index.html">Startseite</a><span aria-hidden="true">/</span><span>{title.replace("<br>"," ")}</span></nav><header class="page-hero"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{lead}</p></header>'
def cta(base='../'):
 return f'<section class="support"><div><p class="eyebrow">Eine gemeinsame Richtung</p><h2>Die Mitte braucht<br>Menschen mit Haltung.</h2></div><a class="button" href="{base}jetzt-unterzeichnen/index.html">Jetzt unterzeichnen →</a></section>'
def write(route,title,main):
 base='../'*(len(Path(route).parts)-1)
 target=DIST/route;target.parent.mkdir(parents=True,exist_ok=True)
 target.write_text(shell(title,route,base,main))

POSTS=[
 {'slug':'rheinland-pfalz-am-limit','title':'Rheinland-Pfalz am Limit – warum dieser Wahlkampf über die Zukunft der politischen Mitte entscheidet','date':'27. Dezember 2025','iso':'2025-12-27','author':'Marco Pusceddu','url':ORIGINAL+'rheinland-pfalz-am-limit-warum-dieser-wahlkampf-ueber-die-zukunft-der-politischen-mitte-entscheidet/','summary':'Kommunale Handlungsfähigkeit, verlässliche Finanzierung und die Verantwortung der politischen Mitte. Ein Beitrag aus Rheinland-Pfalz im damaligen Wahlkampfkontext.','body':'Marco Pusceddu verbindet die Frage nach dem Profil der CDU mit dem Alltag der Gemeinden. Er beschreibt begrenzte finanzielle Spielräume und die Erwartungen an funktionierende öffentliche Angebote. Vertrauen entsteht aus seiner Sicht durch nachvollziehbare Prioritäten und verlässliches Handeln vor Ort. Der Text wurde im Dezember 2025 vor der Landtagswahl veröffentlicht; seine Wahlkampfaussagen und Zahlen sind historisch einzuordnen.'},
 {'slug':'was-compassmitte-fuer-mich-bedeutet','title':'Was CompassMitte für mich bedeutet','date':'1. Dezember 2025','iso':'2025-12-01','author':'Luis Lohaus','url':ORIGINAL+'was-compassmitte-fuer-mich-bedeutet/','summary':'Eine persönliche Perspektive auf die Union als Volkspartei und auf die Bedeutung von Maß, Mitte und politischem Stil.','body':'Luis Lohaus beschreibt CompassMitte als eine Plattform, die unterschiedliche Menschen in der Union zusammenbringen soll. Er betont die Nähe der Kommunalpolitik zum Alltag und wirbt dafür, die sozialen, liberalen und konservativen Perspektiven gemeinsam zur Geltung zu bringen. Inhalt und Umgangston gehören für ihn zusammen. Sein Beitrag blickt auf Erfahrungen der Union zurück und fragt, wie sie gesellschaftliche Breite zurückgewinnen kann.'},
 {'slug':'lobbyverband-verliert-seinen-kompass','title':'Lobbyverband verliert seinen Kompass','date':'28. November 2025','iso':'2025-11-28','author':'Dieter Breymann','url':ORIGINAL+'lobbyverband-verliert-seinen-kompass/','summary':'Dieter Breymann zur demokratischen Verantwortung von Unternehmen und ihren Verbänden.','body':'Der Originalbeitrag thematisiert einen damaligen Vorstoß des Verbands der Familienunternehmer. Er verbindet die Kritik mit der demokratischen Verantwortung wirtschaftlicher Interessenvertretung und verweist auf eine Nachricht von Dieter Breymann. Das dort eingebundene Video wird in dieser Vorschau nicht automatisch geladen.'},
 {'slug':'anmerkungen-zum-28-punkte-kapitulationsdiktat','title':'Anmerkungen zum 28-Punkte-Kapitulationsdiktat','date':'25. November 2025','iso':'2025-11-25','author':'Redaktion · mit Anmerkungen von Ruprecht Polenz','url':ORIGINAL+'anmerkungen-zum-28-punkte-kapitulationsdiktat/','summary':'Einordnung eines damaligen Verhandlungsvorschlags und der Frage nach Sicherheit und Souveränität der Ukraine.','body':'Der Originaleintrag stellt Anmerkungen von Ruprecht Polenz zu einem damaligen 28-Punkte-Vorschlag vor. Im Mittelpunkt stehen die Souveränität der Ukraine sowie ein Frieden, der Freiheit und Sicherheit berücksichtigt. Die vollständigen Anmerkungen sind auf der bestehenden Website als Dokument verlinkt. Dieser Beitrag gehört in den historischen Kontext vom November 2025.'},
]
(DIST/'assets/beitrag-daten.json').write_text(json.dumps(POSTS,ensure_ascii=False,indent=2))
def postcard(p,base='../'):
 return f'<article class="post-card"><p class="eyebrow">Mitgliederbeitrag · <time datetime="{p["iso"]}">{p["date"]}</time></p><h2><a href="{base}beitraege/{p["slug"]}/index.html">{p["title"]}</a></h2><p>{p["summary"]}</p><div class="post-bottom"><span>{p["author"]}</span><a class="text-link" href="{base}beitraege/{p["slug"]}/index.html">Zum Beitrag →</a></div></article>'

home=f'''<main id="inhalt"><div class="wrap"><section class="hero"><div><p class="eyebrow">Christdemokratie mit Richtung</p><h1>Auf das <em>C</em><br>kommt es an.</h1><p class="lead">Für eine CDU, die Menschen verbindet. Sozial, liberal und konservativ. Getragen von christlicher Verantwortung und einer klaren Haltung für unsere Demokratie.</p><div class="actions"><a class="button accent" href="die-idee/index.html">Den Urtext lesen →</a><a class="text-link" href="jetzt-unterzeichnen/index.html">Jetzt unterzeichnen →</a></div></div><div class="compass" aria-label="Das C gibt die Richtung vor"><span class="compass-label north">HALTUNG</span><span class="compass-c" aria-hidden="true">C</span><span class="compass-label south">DIE MITTE HAT RICHTUNG.</span></div></section><section class="urtext-feature" aria-labelledby="urtext-start"><div><p class="eyebrow">Das Grundsatzpapier von CompassMitte</p><h2 id="urtext-start">Dafür setzen<br>wir uns ein.</h2><p class="fine">14 Punkte · Vollständiger Originaltext</p></div><div><blockquote>„Wir wollen eine CDU/CSU, der man das ‚C‘ nicht nur in Sonntagsreden anmerkt.“</blockquote><p>Der Urtext ist die Grundlage von CompassMitte. Hier stehen unsere gemeinsamen Überzeugungen und politischen Forderungen.</p><div class="actions"><a class="button accent" href="die-idee/index.html#urtext">Alle 14 Punkte lesen →</a><a class="text-link" href="assets/compass-mitte-urtext.pdf">Original als PDF ↗</a></div></div></section><div class="strap"><p>Menschenwürde. Verantwortung. Zusammenhalt.</p><span>Eine Plattform in der CDU.<br>Im Gespräch. In der Sache. Vor Ort.</span></div><link rel="stylesheet" href="assets/unterstuetzung.css"><a class="supporter-count" href="die-unterstuetzer/index.html"><span class="supporter-count-copy"><strong>Über 500</strong><span>Menschen unterstützen CompassMitte.</span></span><span class="text-link">Zur Namensliste →</span></a><section class="participation-grid" aria-label="Mitmachen und informiert bleiben"><div class="participation"><p class="eyebrow">Jetzt direkt unterzeichnen</p><h2>Eine gemeinsame<br>Richtung unterstützen.</h2><p>Die Grundsätze kennenlernen und ein Zeichen für eine starke politische Mitte setzen.</p><a class="button accent" href="jetzt-unterzeichnen/index.html">Zur Unterzeichnung →</a></div><div class="participation newsletter"><p class="eyebrow">Newsletter</p><h2>Aus der Mitte.<br>Direkt ins Postfach.</h2><p>Beiträge, Perspektiven und Impulse aus dem Netzwerk. Unabhängig von einer Unterzeichnung.</p><form data-demo-form data-kind="newsletter"><label for="newsletter-email">E-Mail-Adresse</label><div class="input-action"><input id="newsletter-email" type="email" autocomplete="email" placeholder="Ihre E-Mail-Adresse" required><button class="button" type="button" data-demo-submit disabled>Anmeldung testen →</button></div><p class="fine">Vorschau: Es wird kein Newsletter bestellt.</p><p class="form-status" role="status" aria-live="polite"></p></form></div></section><section class="section" aria-labelledby="news-title"><div class="section-head"><div><p class="eyebrow">News · Aus der Mitte</p><h2 id="news-title">Gedanken, die weiterführen.</h2></div><a class="text-link" href="beitraege/index.html">Alle Beiträge →</a></div><div class="post-grid">{postcard(POSTS[0],'')}{postcard(POSTS[1],'')}</div><a class="archive-line" href="blog/index.html"><span><small>Presse · Tagesspiegel · 4. Dezember 2025</small><strong>Wahlstudie</strong></span><span>Zum Newsroom →</span></a></section><section class="people section" style="padding-top:35px"><div class="people-intro"><p class="eyebrow">Unterzeichnerinnen &amp; Unterzeichner</p><h2>Eine Haltung.<br>Viele Perspektiven.</h2><p>CompassMitte wird von Menschen mit unterschiedlichen Erfahrungen getragen.</p><a class="text-link" href="die-unterstuetzer/index.html">Die veröffentlichte Liste ansehen →</a></div><div><div class="person"><div><h3>Monica Wüllner</h3><small>Erstunterzeichnerin</small></div></div><div class="person"><div><h3>Ruprecht Polenz</h3><small>Erstunterzeichner</small></div></div><div class="person"><div><h3>Marco Pusceddu</h3><small>Erstunterzeichner</small></div></div></div></section></div></main>'''
write('index.html','Auf das C kommt es an',home)

