idea='<main id="inhalt" class="wrap">'+heading('Dafür setzen<br>wir uns ein.','Die Idee · Der Urtext','Das Grundsatzpapier von CompassMitte. Alle 14 Punkte im ursprünglichen Wortlaut, direkt hier lesbar.')+'<div class="urtext-toolbar"><a class="button accent" href="../assets/compass-mitte-urtext.pdf">Original-PDF öffnen ↗</a><a class="text-link" href="#urtext">Zum vollständigen Text ↓</a></div><article id="urtext" class="urtext-document" aria-labelledby="urtext-title"><header><p class="eyebrow">Vollständiger Originaltext</p><h2 id="urtext-title">Plattform „CompassMitte“</h2><p class="fine">Übernommen aus dem auf der bestehenden Website verlinkten Grundsatzpapier. Zeitbezüge und Aussagen entsprechen der Originalfassung.</p></header>'+urtext+'<p class="fine urtext-source"><a href="https://www.compassmitte.net/wp-content/uploads/2025/11/CompassMitte-Idee-1.pdf">Zur PDF-Quelle auf compassmitte.net ↗</a></p></article><details class="urtext-summary"><summary>Ergänzend: die Grundsätze in sechs Themen</summary><p class="fine">Redaktionelle Kurzfassung zur Orientierung. Maßgeblich ist der vollständige Urtext oben.</p>'+summary+'</details>'+questions+cta()+'</main>'
